\label{thm:main}
  Let $g$ be a regular Doeblin function that satisfies \eqref{eq:assumption}, namely
  \begin{equation*}
    \limsup_{n\to\infty}\frac{r_n}{\sqrt{n}^{-1}} < 2, \text{ with } r_n:=\operatorname{var}_n \log g.
  \end{equation*}
  Then $g$ possesses a unique Doeblin measure.

\label{lem:dtv}
  Assume~\eqref{eq:assumption} holds. Let $N\in{\mathbb{N}}$. For a large enough integer $K\ge2$ the minimum success probability satisfies
  \begin{equation}
    \inf_{B \in {\mathbb{N}} ;\x,\tilde\x \in\X}
    \left\{ \zeta_{x,\tilde\x}^b(S) : \kappa(x,\tilde\x) \ge B \ge N\right\}
    > \frac 1K
    \label{eq:dtv}
  \end{equation}
  where $b = b(B) = (K-1)\cdot B$.

\label{prop:limsupY}
  Under the assumptions of Lemma \ref{lem:dtv}
  \begin{equation}\label{eq:limsupY}
    \limsup_{n\to\infty} \frac{Y^{(n)}}{n} = 1  \; a.s.
  \end{equation}

\label{thm:counter}
  There exists a continuous Doeblin function $g>0$ on $\X = A^{\mathbb{N}}$, $|A|<\infty$, for
  which \eqref{goal} holds.

\label{thm:noptwise}
  There exists a Doeblin function $g$ with a unique Doeblin measure such that
  we do not have pointwise convergence of the sequence of iterates of the associated transfer operator $\mathit{L}_g$.
